#!/usr/bin/perl
use strict;
use warnings;

# 子程序1: 计算偶数的平方和
sub sum_of_squares {
    my @numbers = @_;
    my $sum = 0;
    foreach my $num (@numbers) {
        if ($num % 2 == 0) {
            $sum += $num ** 2;
        }
    }
    return $sum;
}

# 子程序2: 找出出现次数最多的字符及其出现次数
sub most_frequent_char {
    my ($string) = @_;
    my %char_count;
    foreach my $char (split //, $string) {
        next if $char eq ' '; # 忽略空格
        $char_count{$char}++;
    }

    my ($max_char, $max_count) = ('', 0);
    while (my ($key, $value) = each %char_count) {
        if ($value > $max_count) {
            $max_char = $key;
            $max_count = $value;
        }
    }
    return ($max_char, $max_count);
}

