#!/usr/bin/perl
use strict;
use warnings;
use List::Util qw(min max);

# 子程序计算平均值
sub calculate_average {
    my @numbers = @_;
    return undef if scalar(@numbers) == 0; # 处理空列表的情况
    my $sum = 0;
    foreach my $num (@numbers) {
        $sum += $num;
    }
    return $sum / scalar(@numbers);
}

# 子程序找出最大值和最小值及其索引位置
sub find_min_max_indices {
    my @numbers = @_;
    return undef, undef if scalar(@numbers) == 0; # 处理空列表的情况
    my $min_value = min(@numbers);
    my $max_value = max(@numbers);
    my $min_index = first_index { $_ == $min_value } @numbers;
    my $max_index = first_index { $_ == $max_value } @numbers;
    return ($min_index, $max_index);
}

# 主程序
